const DATES={
 pt:{ms:['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'],ml:['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'],wd:['DOM','SEG','TER','QUA','QUI','SEX','SÁB'],wd1:['D','S','T','Q','Q','S','S'],loc:'pt-BR'},
 en:{ms:['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'],ml:['January','February','March','April','May','June','July','August','September','October','November','December'],wd:['SUN','MON','TUE','WED','THU','FRI','SAT'],wd1:['S','M','T','W','T','F','S'],loc:'en-US'},
};
let LANG='pt';
function t(s,v){let r=LANG==='en'?(EN[s]??s):s;if(v)for(const k in v)r=r.split('{'+k+'}').join(v[k]);return r}
const L=()=>DATES[LANG];

/* ================= Data ================= */
/* As pessoas vêm do servidor: cada família tem as suas. */
const PEOPLE=[];
const PALETTE=['#FBB28B','#6B515E','#F7E289','#A9AE97','#DBC0E8','#EA5E86','#F9A2C5'];
const ROLES=['Mãe','Pai','Filha','Filho','Outro'];
function setPeople(rows,resetFilter){
  PEOPLE.length=0;
  rows.forEach(m=>PEOPLE.push({id:m.id,name:m.name,role:m.role,color:m.color,shape:m.shape,admin:!!m.is_admin}));
  if(resetFilter||!st.filter)st.filter=new Set([...PEOPLE.map(p=>p.id),'familia']);
  else PEOPLE.forEach(p=>{if(!st.known||!st.known.has(p.id))st.filter.add(p.id)});
  st.known=new Set(PEOPLE.map(p=>p.id));
}
const FAMILY={id:'familia',name:'Família toda',role:'Todos',color:'#F76F54',shape:'family'};
const admins=()=>PEOPLE.filter(p=>p.admin).map(p=>p.name).join(LANG==='en'?' and ':' e ');
const pname=p=>p.id==='familia'?t('Família toda'):p.name;
const C={bdayFam:'#47B5A8',bdayInd:'#A3C1E2',family:'#F76F54'};
const START=6,END=24;
const REPEAT_K=['none','daily','weekly','biweekly','monthly'];
const REPEAT_PT={none:'Não repete',daily:'Todo dia',weekly:'Toda semana',biweekly:'A cada 15 dias',monthly:'Todo mês'};
const REMIND_K=['-1','0','10','30','60','1440'];
const REMIND_PT={'-1':'Sem lembrete','0':'Na hora','10':'10 min antes','30':'30 min antes','60':'1 hora antes','1440':'1 dia antes'};
const rep=k=>t(REPEAT_PT[k]),rem=k=>t(REMIND_PT[String(k)]);

const pad=n=>String(n).padStart(2,'0');
const key=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const parse=k=>{const[y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d)};
const addDays=(d,n)=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+n);
const dayNum=d=>Math.round(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5);
const startOfWeek=d=>addDays(d,-d.getDay());
const toMin=s=>{const[h,m]=s.split(':').map(Number);return h*60+m};
const today=()=>{const n=new Date();return new Date(n.getFullYear(),n.getMonth(),n.getDate())};
const sameDay=(a,b)=>dayNum(a)===dayNum(b);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2,12);
const fmtLong=d=>new Intl.DateTimeFormat(L().loc,{weekday:'long',day:'numeric',month:'long'}).format(d);
const dm=(d,m)=>t('{d} de {m}',{d,m:L().ml[m]});
const person=id=>id==='familia'?FAMILY:PEOPLE.find(p=>p.id===id);
const colorOf=id=>person(id)?.color||'#999';
function textOn(hex){const n=parseInt(hex.slice(1),16),r=(n>>16&255)/255,g=(n>>8&255)/255,b=(n&255)/255;
  const f=c=>c<=.03928?c/12.92:((c+.055)/1.055)**2.4;const Lm=.2126*f(r)+.7152*f(g)+.0722*f(b);return Lm>.18?'#1E2438':'#F6EFE4'}

/* Os dados ficam no servidor (backend.js). Aqui só a cópia em memória e as preferências do aparelho. */
const PREFS_LS='homebase-prefs';
let db={session:null,prefs:{theme:'dark',notif:true,lang:'pt',appIcon:1},events:[],birthdays:[],lists:{mercado:[],farmacia:[]},todos:{}};
try{const sp=JSON.parse(localStorage.getItem(PREFS_LS)||'{}');['theme','notif','lang'].forEach(k=>{if(sp[k]!=null)db.prefs[k]=sp[k]})}catch(e){}
LANG=db.prefs.lang;
const save=()=>{try{const{theme,notif,lang}=db.prefs;localStorage.setItem(PREFS_LS,JSON.stringify({theme,notif,lang}))}catch(e){}HB.push()};

const st={mode:'familia',view:matchMedia('(max-width:760px)').matches?'dia':'semana',cursor:today(),filter:new Set([...PEOPLE.map(p=>p.id),'familia']),fired:new Set()};
const me=()=>person(db.session);

/* ================= Permissions ================= */
const hiddenEv=e=>!!e.private&&(e.by||e.owner)!==me().id;
const canSeeEvent=ev=>!hiddenEv(ev)&&(me().admin||ev.owner===me().id||ev.owner==='familia');
const canEditEvent=ev=>ev.private?(ev.by||ev.owner)===me().id:(me().admin||ev.owner===me().id);
const canSeeBday=b=>b.vis==='familia'||b.by===me().id||(b.vis==='alguns'&&b.with.includes(me().id));
const canEditBday=b=>b.by===me().id||(me().admin&&b.vis==='familia');
const bdayColor=b=>b.vis==='familia'?C.bdayFam:C.bdayInd;

function occurs(ev,d){const s=parse(ev.date),diff=dayNum(d)-dayNum(s);if(diff<0)return false;if(ev.until&&ev.repeat!=='none'&&dayNum(d)>dayNum(parse(ev.until)))return false;
  switch(ev.repeat){case'none':return diff===0;case'daily':return true;case'weekly':return diff%7===0;case'biweekly':return diff%14===0;case'monthly':return d.getDate()===s.getDate()}return false}
const famView=()=>me().admin&&st.mode!=='eu';
const visibleEvents=()=>(famView()?db.events.filter(e=>st.filter.has(e.owner)):db.events.filter(e=>e.owner===me().id||e.owner==='familia')).filter(e=>!hiddenEv(e));
const eventsOn=(d,list=visibleEvents())=>list.filter(e=>occurs(e,d)).sort((a,b)=>toMin(a.start)-toMin(b.start));
const bdaysOn=d=>db.birthdays.filter(canSeeBday).filter(b=>b.md===`${pad(d.getMonth()+1)}-${pad(d.getDate())}`);
function nextBdays(n=6){const T=today();return db.birthdays.filter(canSeeBday).map(b=>{const[m,dd]=b.md.split('-').map(Number);let d=new Date(T.getFullYear(),m-1,dd);if(d<T)d=new Date(T.getFullYear()+1,m-1,dd);return{b,d,in:dayNum(d)-dayNum(T)}}).sort((a,b)=>a.in-b.in).slice(0,n)}

